-- Create documents table
CREATE TABLE IF NOT EXISTS documents (

    -- Unique ID for every document
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- User who uploaded this document
    user_id UUID NOT NULL,

    -- Original filename provided by the user
    original_filename VARCHAR(255) NOT NULL,

    -- Unique filename generated by our backend
    stored_filename VARCHAR(255) NOT NULL UNIQUE,

    -- Document MIME type (PDF, DOCX, TXT)
    mime_type VARCHAR(100) NOT NULL,

    -- File size in bytes
    file_size BIGINT NOT NULL CHECK (file_size > 0),

    -- Current document processing status
    status VARCHAR(20) NOT NULL DEFAULT 'uploaded'
        CHECK (status IN ('uploaded', 'processing', 'processed', 'failed')),

    -- Document upload timestamp
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Connect documents with users table
    CONSTRAINT fk_documents_user
        FOREIGN KEY (user_id)
        REFERENCES users(id)
        ON DELETE RESTRICT
);

-- Index to quickly find documents uploaded by a user
CREATE INDEX IF NOT EXISTS idx_documents_user_id
ON documents(user_id);

-- Index to retrieve documents in upload-date order
CREATE INDEX IF NOT EXISTS idx_documents_created_at
ON documents(created_at DESC);